import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase, getJob, jobFromRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' }); res.end(JSON.stringify(body));
}
function fail(res: ServerResponse, status: number, code: string, message: string, fields?: {field:string;message:string}[]) {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
async function readBody(req: IncomingMessage): Promise<{text:string; tooLarge:boolean}> {
  let text = '', tooLarge = false;
  for await (const chunk of req) {
    text += Buffer.isBuffer(chunk) ? chunk.toString('utf8') : String(chunk);
    if (text.length > 65536) tooLarge = true;
  }
  return { text, tooLarge };
}
function validate(raw: unknown): { input: string; steps: number; failAttempts: number } | { fields: {field:string;message:string}[] } {
  const fields: {field:string;message:string}[] = [];
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) return { fields: [{ field: 'body', message: 'Must be a JSON object.' }] };
  const value = raw as Record<string, unknown>;
  for (const key of Object.keys(value)) if (!['input','steps','failAttempts'].includes(key)) fields.push({field:key,message:'Unknown field.'});
  if (!Object.hasOwn(value, 'input')) fields.push({field:'input',message:'Required.'});
  else if (typeof value.input !== 'string') fields.push({field:'input',message:'Must be a string.'});
  else if (value.input.length < 1 || value.input.length > 1000 || value.input.trim().length === 0) fields.push({field:'input',message:'Must be 1–1000 characters and not only whitespace.'});
  const steps = Object.hasOwn(value, 'steps') ? value.steps : 5;
  if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({field:'steps',message:'Must be an integer from 1 to 20.'});
  const failAttempts = Object.hasOwn(value, 'failAttempts') ? value.failAttempts : 0;
  if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({field:'failAttempts',message:'Must be an integer from 0 to 5.'});
  if (fields.length) return { fields };
  return { input: value.input as string, steps: steps as number, failAttempts: failAttempts as number };
}

const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/') {
    if (req.method !== 'GET') return fail(res,405,'method_not_allowed','Method not allowed.');
    res.writeHead(200, {'content-type':'text/html; charset=utf-8'}); res.end(uiHtml); return;
  }
  if (pathname === '/health') {
    if (req.method !== 'GET') return fail(res,405,'method_not_allowed','Method not allowed.');
    const row = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id=1').get() as {seen_at:number} | undefined;
    return send(res,200,{status:'ok',worker:row && Date.now()-Number(row.seen_at)<=3000 ? 'up':'down'});
  }
  if (pathname === '/api/jobs') {
    if (req.method === 'GET') {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as Record<string,unknown>[];
      return send(res,200,{jobs:rows.map(jobFromRow)});
    }
    if (req.method !== 'POST') return fail(res,405,'method_not_allowed','Method not allowed.');
    const contentType = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) return fail(res,400,'invalid_request','Invalid request.',[{field:'body',message:'Content-Type must be application/json.'}]);
    const keyHeader = req.headers['idempotency-key'];
    if (Array.isArray(keyHeader) || (keyHeader !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(keyHeader))) return fail(res,400,'invalid_request','Invalid request.',[{field:'Idempotency-Key',message:'Must match ^[A-Za-z0-9_-]{1,128}$.'}]);
    const body = await readBody(req);
    if (body.tooLarge) return fail(res,400,'invalid_request','Invalid request.',[{field:'body',message:'Body is too large.'}]);
    let parsed: unknown;
    try { parsed = JSON.parse(body.text); } catch { return fail(res,400,'invalid_request','Invalid request.',[{field:'body',message:'Malformed JSON.'}]); }
    const valid = validate(parsed);
    if ('fields' in valid) return fail(res,400,'invalid_request','Invalid request.',valid.fields);
    const payload = JSON.stringify(valid);
    const key = keyHeader as string | undefined;
    const now = new Date().toISOString();
    db.exec('BEGIN IMMEDIATE');
    try {
      if (key) {
        const previous = db.prepare('SELECT payload,job_id FROM idempotency WHERE key=?').get(key) as {payload:string;job_id:string}|undefined;
        if (previous) {
          db.exec('COMMIT');
          if (previous.payload !== payload) return fail(res,409,'idempotency_conflict','This Idempotency-Key was already used with a different payload.');
          const job = getJob(db,previous.job_id); if (job) return send(res,200,job);
        }
      }
      const id = randomUUID();
      db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,created_at,updated_at) VALUES(?,?,?,?,?,?,?)`).run(id,'queued',valid.input,valid.steps,valid.failAttempts,now,now);
      if (key) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(key,payload,id);
      db.exec('COMMIT');
      return send(res,201,getJob(db,id));
    } catch (error) { db.exec('ROLLBACK'); throw error; }
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    if (req.method !== 'GET') return fail(res,405,'method_not_allowed','Method not allowed.');
    let id: string; try { id = decodeURIComponent(match[1]); } catch { return fail(res,404,'not_found','Job not found.'); }
    const job = getJob(db,id); return job ? send(res,200,job) : fail(res,404,'not_found','Job not found.');
  }
  return fail(res,404,'not_found','Not found.');
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
function shutdown() { server.close(() => { db.close(); process.exit(0); }); }
process.on('SIGTERM',shutdown); process.on('SIGINT',shutdown);

