6	  <title>Job tracker</title>
7	  <style>
8	    body { max-width: 760px; margin: 2rem auto; padding: 0 1rem; font: 16px/1.5 system-ui, sans-serif; color: #202124; }
9	    form { display: grid; grid-template-columns: 1fr 1fr; gap: .8rem; padding: 1rem; border: 1px solid #ccd0d5; border-radius: 8px; }
10	    label { display: grid; gap: .25rem; } label:first-child { grid-column: 1 / -1; }
11	    input, button { font: inherit; padding: .45rem; } button { grid-column: 1 / -1; cursor: pointer; }
12	    [role="alert"] { color: #a01818; min-height: 1.5em; }
13	    #job-list { list-style: none; margin: 0; padding: 0; }
14	    [data-testid="job-item"] { padding: .8rem 0; border-bottom: 1px solid #ddd; }
15	    .meta { color: #555; }
16	  </style>
17	</head>
18	<body>
19	  <h1>Job tracker</h1>
20	  <form data-testid="job-form" id="job-form">
21	    <label>Input <input data-testid="job-input" name="input" type="text" maxlength="1000"></label>
22	    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" value="5"></label>
23	    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" value="0"></label>
24	    <button data-testid="job-submit" type="submit">Submit job</button>
25	  </form>
26	  <div data-testid="form-error" id="form-error" role="alert"></div>
27	  <h2>Jobs</h2>
28	  <ul data-testid="job-list" id="job-list"></ul>
29	  <script>
30	    const form = document.querySelector('[data-testid="job-form"]');
31	    const errorRegion = document.querySelector('[data-testid="form-error"]');
32	    const list = document.querySelector('[data-testid="job-list"]');
33	    async function refresh() {
34	      try {
35	        const response = await fetch('/api/jobs');
36	        if (!response.ok) return;
37	        const { jobs } = await response.json();
38	        list.replaceChildren(...jobs.map(job => {
39	          const item = document.createElement('li'); item.dataset.testid = 'job-item'; item.dataset.jobId = job.id;
40	          const heading = document.createElement('strong'); heading.textContent = job.input;
41	          const status = document.createElement('span'); status.dataset.testid = 'job-status'; status.textContent = job.status;
42	          const meta = document.createElement('div'); meta.className = 'meta';
43	          meta.append('Status: ', status, ' · Progress: ');
44	          const progress = document.createElement('span'); progress.dataset.testid = 'job-progress'; progress.textContent = `${job.progress.completed}/${job.progress.total}`; meta.append(progress);
45	          const result = document.createElement('div'); result.dataset.testid = 'job-result';
46	          result.textContent = job.result?.output ?? job.error ?? '';
47	          item.append(heading, meta, result); return item;
48	        }));
49	      } catch { /* A later poll will recover when the server is available. */ }
50	    }
51	    form.addEventListener('submit', async event => {
52	      event.preventDefault(); errorRegion.textContent = '';
53	      const data = new FormData(form);
54	      const payload = { input: String(data.get('input') ?? ''), steps: Number(data.get('steps')), failAttempts: Number(data.get('failAttempts')) };
55	      try {
56	        const response = await fetch('/api/jobs', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payload) });
57	        const body = await response.json();
58	        if (!response.ok) {
59	          const error = body.error;
60	          errorRegion.textContent = error?.fields?.length
61	            ? `${error.message} ${error.fields.map(field => `${field.field}: ${field.message}`).join(' ')}`
62	            : (error?.message ?? 'Could not submit job.');
63	        } else { form.elements.input.value = ''; await refresh(); }
64	      } catch { errorRegion.textContent = 'Could not submit job. Please try again.'; }
65	    });
66	    refresh(); setInterval(refresh, 750);
67	  </script>
68	</body>
